with flattened_attrs as (select id, host, log_ts, level, status_code, payload_json, context, array_contains(map_keys(context), 'trace') as has_trace, coalesce(context['version'], 'none') as version_or_default, get_json_object(payload_json, '$.user.id') as user_id, coalesce(context['trace'], 'direct') as trace_or_default from app_logs) select case when status_code >= 443 then 'PREMIUM' else 'STANDARD' end as status_code_tier, min(log_ts) as first_log_ts, count(*) as num_rows from flattened_attrs group by 1 order by status_code_tier
